"""One-time integration of collection labels and the original official errata."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def replace(path,old,new):
    p=ROOT/path;s=p.read_text(encoding='utf8');assert old in s,(path,old);p.write_text(s.replace(old,new),encoding='utf8')

replace('scripts/import_library.py','CACHE,EDITION,paper_key,edition_of','CACHE,EDITION,paper_key,edition_of,config\nfrom source_info import source_name,paper_name')
replace('scripts/import_library.py','READERS={}','READERS={}\nCORRECTIONS=json.loads((ROOT/"data/answer_corrections32.json").read_text(encoding="utf8"))["corrections"] if EDITION==32 else {}')
replace('scripts/import_library.py','def spans(k,paper,number,heading=False):','def spans(k,paper,number,heading=False):\n    correction=CORRECTIONS.get(f"{paper}-{number}")\n    if k=="a" and correction:return correction["effectiveRanges"]')
