replace('scripts/import_library.py',"'answerPages':pages(ar),'pdfReady':True", "'answerPages':pages(CORRECTIONS.get(f'{paper}-{number}',{}).get('originalRanges',ar)),'pdfReady':True,'sourcePaperLabel':paper_name(EDITION,paper),'series':config.get('series','annual')")
replace('scripts/import_library.py',"        records.append({'number':number", "        correction=CORRECTIONS.get(f'{paper}-{number}')\n        if correction:items[-1]['answerCorrectionPages']='、'.join(map(str,correction['errataPages']))\n        records.append({'number':number")
