replace('scripts/fast_pdf.py',"            title=f'第{entry[\"number\"]}题 · 第{entry[\"sourceEdition\"]}届模拟试题{entry[\"sourcePaper\"]}原第{entry[\"sourceNumber\"]}题'", "            from source_info import source_name\n            title=f'第{entry[\"number\"]}题 · {source_name(entry[\"sourceEdition\"],entry[\"sourcePaper\"],compact=True)}原第{entry[\"sourceNumber\"]}题'")
replace('scripts/rebuild_numbering.py',"'pdf_form_cache.py']","'pdf_form_cache.py','source_info.py']")
