replace('scripts/audit_library.py',"sources=read(ROOT/'sources/manifest.json')['editions'][str(e)]['originalFiles']","entry=read(ROOT/'sources/manifest.json')['editions'][str(e)]\n        sources=entry['originalFiles']+entry.get('workingFiles',[])\n        config=read(ROOT/'data/editions.json')[str(e)]")
